/*!
 * Themeasy — Nested Tabs editor element type
 *
 * PHP's Widget_Nested_Base is only half of Elementor's nesting contract: it
 * declares `support_nesting` and the children defaults, but the editor still
 * draws the widget with the plain BaseWidgetView, whose child views are never
 * attached to the DOM. The panels then render EMPTY on the canvas while the
 * document model already holds the full nested tree — the exact symptom this
 * file exists to remove.
 *
 * The other half is registering an element type whose view extends the
 * nested-elements NestedView, which is what teaches Elementor to mount the
 * child containers into the widget's own placeholder
 * (get_default_children_placeholder_selector -> `.tms-nested-tabs__panels`).
 *
 * The view also runs the canvas like Elementor's own Tabs: one panel visible
 * at a time, switched by a click on its tab, by the panel's repeater row, or
 * by selecting an element inside it from the Structure panel.
 *
 * Editor-only. The frontend needs none of this: render() prints the children
 * itself and Bootstrap's data-api drives the switching.
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window) {
  'use strict'

  const WIDGET_TYPE = 'themeasy-nested-tabs'

  /**
   * Register the element type.
   *
   * Runs on `elementor/nested-element-type-loaded` — the event Elementor fires
   * once NestedElementBase and the nested-elements component exist. Registering
   * any earlier throws. The PHP side prints this file before the editor loader
   * so the listener is attached in time; the direct call at the bottom covers a
   * script that still arrives after the event (an optimizer reordering footer
   * scripts), which is why both entry points must be idempotent.
   */
  function registerNestedTabs() {
    const elementor = window.elementor

    if (!elementor || !elementor.elementsManager || !elementor.modules) {
      return
    }

    // Already registered by the other entry point: a second registration throws.
    if (elementor.elementsManager.elementTypes && elementor.elementsManager.elementTypes[WIDGET_TYPE]) {
      return
    }

    const NestedElementBase = elementor.modules.elements
      && elementor.modules.elements.types
      && elementor.modules.elements.types.NestedElementBase

    // While the nested-elements module is still loading this slot holds a
    // Promise, not the class.
    if (typeof NestedElementBase !== 'function') {
      return
    }

    let NestedView

    try {
      NestedView = window.$e.components.get('nested-elements').exports.NestedView
    } catch (e) {
      return
    }

    if (!NestedView) return

    /**
     * The panel view.
     *
     * Pairs each child container with the button that controls it (the
     * buttons come from content_template(), the containers from Elementor) and
     * shows one panel at a time, the way Elementor's own Tabs does on the
     * canvas.
     *
     * The active tab is Elementor's `activeItemIndex` edit setting (1-based),
     * written by `document/repeater/select` from three places: a click on a
     * tab in the canvas (onTabClick), opening a row in the panel's repeater,
     * and Elementor's nested hook when an element inside a hidden tab is
     * selected from the Structure panel. The edit setting is never saved, but
     * the command is a history command, so a canvas click flags the document
     * as modified — exactly what Elementor's own Tabs does.
     */
    class ThemeasyNestedTabsView extends NestedView {
      initialize(...args) {
        super.initialize(...args)

        this.listenTo(this.model.get('editSettings'), 'change:activeItemIndex', this.syncActiveTab)
      }

      events() {
        const events = super.events()

        // Delegated handlers run before NestedView's own `click`, which stops
        // the event (so Bootstrap's data-api never sees it) and selects the
        // widget — the same pairing as a click on Elementor's Tabs.
        events['click .nav-link'] = 'onTabClick'

        return events
      }

      onRender(...args) {
        super.onRender(...args)

        // The template marks the first tab active; the edit setting wins.
        this.syncActiveTab()
      }

      onAddChild(childView) {
        this.wirePanel(childView)
        this.setPanelState(childView, this.getActiveIndex())
      }

      /**
       * Removing a tab shifts every later panel down one slot, but Elementor
       * does not re-render the survivors, so the ids they got in onAddChild
       * would keep pointing at the old buttons: re-pair them all.
       */
      onRemoveChild() {
        this.children.each(childView => this.wirePanel(childView))
        this.syncActiveTab()
      }

      onTabClick(event) {
        const index = this.getTabButtons().index(event.currentTarget)

        // A `.nav-link` from a widget living inside one of the panels.
        if (index < 0) {
          return
        }

        window.$e.run('document/repeater/select', {
          container: this.getContainer(),
          index: index + 1
        })
      }

      /**
       * Only this widget's own strip — a Nested Tabs dropped inside one of the
       * panels brings buttons of its own.
       */
      getTabButtons() {
        return this.$el.find('.tms-nested-tabs').first().children('.nav').find('.nav-link')
      }

      /**
       * The active tab as a 0-based index, clamped: removing the last tab
       * leaves the edit setting pointing past the end.
       */
      getActiveIndex() {
        const requested = (this.model.get('editSettings').get('activeItemIndex') || 1) - 1

        return Math.max(0, Math.min(requested, this.collection.length - 1))
      }

      syncActiveTab() {
        const active = this.getActiveIndex()

        this.getTabButtons().each((index, button) => {
          button.classList.toggle('active', index === active)
          button.setAttribute('aria-selected', index === active ? 'true' : 'false')
        })

        this.children.each(childView => this.setPanelState(childView, active))
      }

      setPanelState(childView, active) {
        // `active` is the class the stylesheet keys the hidden state on, on the
        // canvas and on the front alike.
        childView.$el.toggleClass('active', this.collection.indexOf(childView.model) === active)
      }

      wirePanel(childView) {
        // The live position in the children collection, never an index stamped
        // at render time: that one goes stale on the remove path above.
        const index = this.collection.indexOf(childView.model)
        const button = this.getTabButtons().eq(index)

        // Both ids are READ off the rendered strip rather than rebuilt here:
        // the template already owns the id scheme, and a second copy of it in
        // JS is exactly the kind of thing that drifts silently.
        childView.$el.attr({
          id: button.attr('aria-controls') || '',
          role: 'tabpanel',
          'aria-labelledby': button.attr('id') || ''
        })

        childView.$el.addClass('tms-nested-tabs__panel')
      }
    }

    class ThemeasyNestedTabsType extends NestedElementBase {
      getType() {
        return WIDGET_TYPE
      }

      getView() {
        return ThemeasyNestedTabsView
      }
    }

    elementor.elementsManager.registerElementType(new ThemeasyNestedTabsType())
  }

  if (window.elementorCommon && window.elementorCommon.elements && window.elementorCommon.elements.$window) {
    window.elementorCommon.elements.$window.on('elementor/nested-element-type-loaded', registerNestedTabs)
  }

  // The event may already be gone; register now if everything it announces is
  // in place (a no-op on the normal path, where elementor has not started yet).
  registerNestedTabs()
})(window)
